INSERT INTO order_detail (id, name, image, order_id, dish_id, setmeal_id, dish_flavor, "number", amount) SELECT seq_order_detail.NEXTVAL, A.* FROM (
SELECT #{od.name}, #{od.image}, #{od.orderId}, #{od.dishId, jdbcType=NULL}, #{od.setmealId, jdbcType=NULL}, #{od.dishFlavor, jdbcType=NULL}, #{od.number}, #{od.amount} FROM DUAL
) A
